const want = {"itbi": {"devido": true, "base": 0, "fundamento": ""}, "integralizacao_imovel": {"valor_recomendado": 0, "ganho_capital_pf": 0}, "pro_labore_minimo_recomendado_mensal": {"Marina": 0, "Felipe": 0, "Luana": 0}, "distribuicao_mensal_pretendida": 50000, "irrf_dividendos_2026_estimado_mensal": 0, "simples_possivel": true};
function shape(o){ if (Array.isArray(o)) return ['array']; if (o && typeof o==='object') return Object.keys(o).sort().map(k=>k+':'+shape(o[k])[0]).join(','); return typeof o; }
function cmp(a,b,path=''){
  const out=[];
  for (const k of Object.keys(b)) {
    const p = path? path+'.'+k : k;
    if (!(k in a)) { out.push('MISSING '+p); continue; }
    if (typeof b[k]==='object') { out.push(...cmp(a[k], b[k], p)); continue; }
    if (typeof a[k] !== typeof b[k]) out.push('TYPE '+p+' got '+typeof a[k]+' want '+typeof b[k]);
  }
  for (const k of Object.keys(a)) if (!(k in b)) out.push('EXTRA '+(path?path+'.'+k:k));
